    int64_t i = begin + tid;
    #pragma unroll 2
    for (; i < end; i += THREADS) {
      float4 a = mX4(row, i);
      sum += a.x + a.y + a.z + a.w;
      sq = fmaf(a.x, a.x, sq);
      sq = fmaf(a.y, a.y, sq);
      sq = fmaf(a.z, a.z, sq);
      sq = fmaf(a.w, a.w, sq);
    }
  } else {
    int64_t i = begin + tid;
    #pragma unroll 4
    for (; i < end; i += THREADS) {
      float a = mX(row, i);
      sum += a;
      sq = fmaf(a, a, sq);
