    float block_sumsq = (lane < NUM_WARPS) ? s_warp_sumsq[lane] : 0.0f;
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
      block_sum += __shfl_down_sync(0xffffffffu, block_sum, offset);
      block_sumsq += __shfl_down_sync(0xffffffffu, block_sumsq, offset);
