  for (int offset = 16; offset > 0; offset >>= 1) {
    rsum += __shfl_down_sync(0xffffffffu, rsum, offset);
    rsumsq += __shfl_down_sync(0xffffffffu, rsumsq, offset);
  }
  if (lane == 0) {
    s_warp_sum[warp] = rsum;
    s_warp_sumsq[warp] = rsumsq;
  }
  __syncthreads();
  if (warp == 0) {
    constexpr int NUM_WARPS = THREADS / 32;
    float row_sum = (lane < NUM_WARPS) ? s_warp_sum[lane] : 0.0f;
    float row_sumsq = (lane < NUM_WARPS) ? s_warp_sumsq[lane] : 0.0f;
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
      row_sum += __shfl_down_sync(0xffffffffu, row_sum, offset);
      row_sumsq += __shfl_down_sync(0xffffffffu, row_sumsq, offset);
    }
