template <int THREADS>
__global__ static void cute_layernorm_partial_kernel(
    const float* __restrict__ X,
    float* __restrict__ partial_stats,
    float* __restrict__ row_stats,
    int* __restrict__ counters,
    int64_t outer,
    int64_t N,
    int blocks_per_row,
    int64_t units_per_block,
    int use_vec,
    float eps)
