    int64_t i = begin + tid;
    for (; i + THREADS < end; i += 2 * THREADS) {
      float4 a = mX4(row, i);
      float4 b = mX4(row, i + THREADS);
      sum0 += a.x + a.y + a.z + a.w;
      sum1 += b.x + b.y + b.z + b.w;
