      float4 a = mX4(row, i);
      sum0 += a.x + a.y + a.z + a.w;
      sq0 = fmaf(a.x, a.x, sq0);
      sq0 = fmaf(a.y, a.y, sq0);
      sq0 = fmaf(a.z, a.z, sq0);
      sq0 = fmaf(a.w, a.w, sq0);
    }
  } else {
    int64_t i = begin + tid;
    for (; i + THREADS < end; i += 2 * THREADS) {
      float a = mX(row, i);
      float b = mX(row, i + THREADS);
      sum0 += a;
      sum1 += b;
      sq0 = fmaf(a, a, sq0);
      sq1 = fmaf(b, b, sq1);
    }
    for (; i < end; i += THREADS) {
      float a = mX(row, i);
      sum0 += a;
      sq0 = fmaf(a, a, sq0);
    }
