  float local_sum = sum0 + sum1;
  float local_sumsq = sq0 + sq1;
  __shared__ float s_warp_sum[THREADS / 32];
  __shared__ float s_warp_sumsq[THREADS / 32];
  const int lane = tid & 31;
  const int warp = tid >> 5;
